import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as flagService from "@/server/services/feature-flag-service";
import { exportActivity, listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("tmpact", "growth");
  detach = registerActivityListeners();
});
afterAll(() => { detach(); cleanup(); });

describe("tmp", () => {
  it("covers flows", async () => {
    const other = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id, name: "Other", slug: "other", key: "OTH", description: null,
      visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
    });
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "T" }));
    await issueService.changeIssueStatus(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, status: "in_progress" });
    await issueService.assignIssue(tenant.actors.admin, { orgId: tenant.org.id, issueId: issue.id, assigneeId: tenant.userIds.member });
    const c = await commentService.createComment(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] });
    await commentService.updateComment(tenant.actors.member, { orgId: tenant.org.id, commentId: c.id, body: "hi2" });
    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: c.id });
    await projectService.updateProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: other.id, name: "Other2" });
    await flagService.toggleFlag(tenant.actors.owner, { orgId: tenant.org.id, flag: "activity_feed" as never, enabled: true }).catch((e) => console.log("flag", String(e)));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const page = await listActivity(tenant.actors.admin, { orgId: tenant.org.id, projectId: tenant.project.id, limit: 100, cursor: null });
    console.log(page.items.map((e) => `${e.action} actor=${e.actorId === tenant.userIds.member ? "member" : e.actorId === tenant.userIds.admin ? "admin" : e.actorId} ${JSON.stringify(e.metadata)}`));
    const all = await listActivity(tenant.actors.admin, { orgId: tenant.org.id, limit: 100, cursor: null });
    console.log(all.items.map((e) => e.action + ":" + (e.projectId === tenant.project.id ? "P" : e.projectId === other.id ? "O" : "-")));

    // late event
    const past = "2020-01-01T00:00:00.000Z" as IsoTimestamp;
    for (let i = 0; i < 250; i++) {
      await emit("project.restored", { orgId: tenant.org.id, actorId: tenant.userIds.admin, occurredAt: past, projectId: other.id });
    }
    const json = JSON.parse(await exportActivity(tenant.actors.admin, { orgId: tenant.org.id, since: past, until: past, format: "json" }));
    expect(json).toHaveLength(250);
    expect(new Set(json.map((e: { id: string }) => e.id)).size).toBe(250);
    const csv = await exportActivity(tenant.actors.admin, { orgId: tenant.org.id, since: "2020-01-01T00:00:00Z" as IsoTimestamp, until: "2020-01-01T00:00:00.000Z" as IsoTimestamp, format: "csv" });
    expect(csv.split("\r\n")).toHaveLength(251);
    await expect(exportActivity(tenant.actors.admin, { orgId: tenant.org.id, since: "2021-01-01T00:00:00.000Z" as IsoTimestamp, until: past, format: "json" })).rejects.toThrow();
  });
});
EOF
